import React, { useState, useMemo, useEffect } from 'react';
import './Table.scss';
import { SwitchProps } from "../switch";
import { DropdownProps } from "../dropdown";
import { TextFieldProps } from "../textField";
import SelectableTable from "./SelectableTable";
import ExpandableTable from "./ExpandableTable";
import DefaultTable from "./DefaultTable";

type SortDirection = "asc" | "desc" | null;

export interface MoreActionItem{
  menuItems: {
    label: string;
  }[];
}

export interface DataItem {
  type: "text" | "country" | "currency" | "number" | "boolean" | "select" | "status" | "action" | "typeStatus" | "multiLineText"; 
  displayName: string;
  value?: string | boolean | number;
  align?: "left" | "right" | "center";
  displayName2?: string;
}

export interface ActionItem {
  icon?: string;
  title?: string;
  href?: string;
  tooltipText?: string;
  tooltipPlacement?: "top" | "bottom" | "left" | "right" | undefined;
  isDisabled?: boolean;
}

export interface TableProps {
  /**
   * Unique identifier for the accordion component
   */
  id:string;

  /**
   * Determines the headers for the main table.
   */
  headers: { 
    sequence: string; 
    displayName: string; 
    tooltipText?: string; 
    align?: "left" | "right" | "center"; 
    width?: string;
    isEditable?: boolean;
    isEditorType? : "text" | "date" | "dropdown" | "switch";
    dropdownOptions?: { label: string; value: string }[];
    isSortable?: boolean;
    sortDirection?: SortDirection;
  }[];

   /**
   * Determines the Sub headers for the sub table.
   */
  subHeaders: { 
    sequence: string; 
    displayName: string; 
    tooltipText?: string; 
    align?: "left" | "right" | "center"; 
    width?: string;
    isEditable?: boolean;
    isEditorType? : "text" | "date" | "dropdown" | "switch";
    dropdownOptions?: { label: string; value: string }[];
  }[];

  /**
   * records to render in table
  */
  records: {
    id: string;
    mainData: DataItem[];  
    subData: {
      parentId: string;
      subId: string;
      data: DataItem[];
    }[];
    mainActionData: ActionItem[],
    subActionData: ActionItem[]
  }[]

 /**
    * Enable first row data to be clickable
   */
  isFirstItemClickable?: boolean;

  /**  
  * Table mode: selectable or expandable rows 
  */
  mode?: "selectable" | "expandable" | "default";

  /**  
   * selectable table's selection type
   * */
  selectionType?: "single" | "multiple"; 

   /**
    * Visual variant for actions
    */
   variant?: "icon" | "label" | "label-and-icon";
 
   /**
    * Pagination behavior
    */
  paginationType?: "table" | "responsive" | "slider" ;
 
   /**
    * Shape of interactive elements
    */
  shape?: "circle" | "square";
 
   /**
    * colour theme
    */
  colour?: "primary" | "secondary" | "tertiary";
 
   /**
    * border outline style
    */
  outline?: "outline" | "none";
   
  /** 
   * action handler
   */
  onActionClick?: (action: string, rowid: string, rowData: DataItem[] ) => void;
 
   /**
    * Determine show/ hide the pagination
    */
  showPagination: boolean;
 
 /** 
    * Text field Props
    */  
  TextFieldProps?: Partial<TextFieldProps>;
 
   /** 
    * action on Text change
    */  
  onTextChange?: (rowId: string,headerSequence: string, value:string) => void;
 
   /** 
    * Switch Props
    */  
  SwitchProps?: Partial<SwitchProps>;
 
   /** 
    * action on switch change
    */  
  OnSwitchChange?: (rowId: string, headerSequence: string, value:boolean) => void;
 
   /** 
    * action on dropdown change
    */  
   OnDropdownChange?: (rowId: string,headerSequence: string, value:string) => void;

   /** 
    * Dropdown Props
    */  
   DropdownProps?: Partial<DropdownProps>;
 
   /** 
    * Pagination total pages
    */ 
   totalPageNumber?: number;
 
   /** 
    * Pagination total Records
    */ 
   totalRecords?: number;
   
   /** 
    * Pagination page change
    */ 
   handlePaginationPageChange?: (page: number ) => void;
 
   /** 
    * Pagination dropdown page change
    */ 
   handlePaginationRowPerPageChange?: (page: number ) => void;

  /** 
   * action on CheckBox Select Row  
  */  
  onRowSelectionChange?: (selectedIds: string[], selectedAll: boolean) => void;

  /** 
   * action on sub  Row  
  */ 
  onSubActionClick?: (action: string, parentId: string, rowid: string, rowData: DataItem[] ) => void;
  
 /** 
   * action on sorting change
  */ 
  onSortAction?: (sequence: string, direction: Exclude<SortDirection, null>) => void;
}

export const Table: React.FC<TableProps> = ({ 
  id,
  headers, 
  subHeaders,
  records, 
  isFirstItemClickable,
  mode="default",
  selectionType="multiple",
  variant="icon", 
  paginationType="table",
  shape, 
  colour="primary",
  outline,
  onActionClick,
  onSubActionClick,
  SwitchProps,
  OnSwitchChange,
  showPagination=true,
  DropdownProps,
  OnDropdownChange,
  totalPageNumber = 0,
  handlePaginationPageChange,
  handlePaginationRowPerPageChange,
  TextFieldProps,
  onTextChange,  
  onRowSelectionChange,
  onSortAction,
  totalRecords
}) => {

  switch (mode) {
  case "selectable":
     return <SelectableTable 
        id={id}
        headers={headers}    
        records={records}
        isFirstItemClickable={isFirstItemClickable}
        selectionType={selectionType}
        variant={variant}
        paginationType={paginationType}
        shape={shape}
        colour={colour}
        outline={outline}
        onActionClick={onActionClick}
        SwitchProps={SwitchProps}
        OnSwitchChange={OnSwitchChange}
        showPagination={showPagination}
        DropdownProps={DropdownProps}
        OnDropdownChange={OnDropdownChange}
        totalPageNumber={totalPageNumber}
        totalRecords={totalRecords}
        handlePaginationPageChange={handlePaginationPageChange}
        handlePaginationRowPerPageChange={handlePaginationRowPerPageChange}
        TextFieldProps={TextFieldProps}
        onTextChange={onTextChange}
        onRowSelectionChange={onRowSelectionChange}
        onSortAction={onSortAction}
      />;
  case "expandable":
   return <ExpandableTable  
        id={id}
        headers={headers}
        subHeaders={subHeaders}
        records={records}
        isFirstItemClickable={isFirstItemClickable}
        variant={variant}
        paginationType={paginationType}
        shape={shape}
        colour={colour}
        outline={outline}
        onActionClick={onActionClick}
        onSubActionClick={onSubActionClick}
        SwitchProps={SwitchProps}
        OnSwitchChange={OnSwitchChange}
        showPagination={showPagination}
        DropdownProps={DropdownProps}
        OnDropdownChange={OnDropdownChange}
        totalPageNumber={totalPageNumber}
        totalRecords={totalRecords}
        handlePaginationPageChange={handlePaginationPageChange}
        handlePaginationRowPerPageChange={handlePaginationRowPerPageChange}
        TextFieldProps={TextFieldProps}
        onTextChange={onTextChange}
        onSortAction={onSortAction}
        />
  case "default":
  default:
   return <DefaultTable  
      id={id}
      headers={headers}      
      records={records}
      isFirstItemClickable={isFirstItemClickable}
      variant={variant}
      paginationType={paginationType}
      shape={shape}
      colour={colour}
      outline={outline}
      onActionClick={onActionClick}      
      SwitchProps={SwitchProps}
      OnSwitchChange={OnSwitchChange}
      showPagination={showPagination}
      DropdownProps={DropdownProps}
      OnDropdownChange={OnDropdownChange}
      totalPageNumber={totalPageNumber}
      totalRecords={totalRecords}
      handlePaginationPageChange={handlePaginationPageChange}
      handlePaginationRowPerPageChange={handlePaginationRowPerPageChange}
      TextFieldProps={TextFieldProps}
      onTextChange={onTextChange}
      onSortAction={onSortAction}
      />;
}};

export default Table;
